import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import './navbar.css';

function Navbar() {
    const [menuOpen, setMenuOpen] = useState(false);

    return (
        <div className="navbar">
            <Link to="/" className="navbar-brand">
                <img src={`${process.env.PUBLIC_URL}/images/logo(1).jpeg`} alt="Chintamani Logo" />
            </Link>
            
            {/* Menu Button (only visible on mobile via CSS) */}
            <button 
                className="menu-btn" 
                onClick={() => setMenuOpen(!menuOpen)}
            >
                ☰
            </button>

            {/* Main Menu */}
            <div className={`navbar-right ${menuOpen ? "active" : ""}`}>
                <Link to="/about" className="navbar-btn" onClick={() => setMenuOpen(false)}>About Us</Link>
                <Link to="/products" className="navbar-btn" onClick={() => setMenuOpen(false)}>Products</Link>
                <Link to="/associates" className="navbar-btn" onClick={() => setMenuOpen(false)}>Associates</Link>
                <Link to="/career" className="navbar-btn" onClick={() => setMenuOpen(false)}>Career</Link>
                <Link to="/contact" className="navbar-btn" onClick={() => setMenuOpen(false)}>Contact</Link>

                {/* Extra Dropdown Links - Mobile */}
                <div className="mobile-extra-links">
                    <Link to="/" onClick={() => setMenuOpen(false)}>Home</Link>
                    <Link to="/products" onClick={() => setMenuOpen(false)}>Offerings</Link>
                    <Link to="/projects" onClick={() => setMenuOpen(false)}>Key Projects</Link>
                </div>
            </div>
        </div>
    );
}

export default Navbar;
